<?php
use Moves\Services\{Contacts,Finance,FinanceContext,OrganizationContext,OrganizationDirectory,OrganizationTeam,ServiceOrders,SessionAuth};
$e=static fn(mixed$v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$org=OrganizationContext::current();if($org===null)return;$user=SessionAuth::current();$canManage=OrganizationTeam::can((int)$user['id'],(int)$org['id'],'finance.manage');$ctx=(int)FinanceContext::currentId();$service=new ServiceOrders((int)$org['id']);try{$data=$service->listing(['status'=>$_GET['situacao']??'','customer_id'=>$_GET['cliente']??null]);$customers=(new Contacts($ctx))->selectableCustomers();$members=OrganizationDirectory::members((int)$org['id']);$finance=new Finance($ctx);$accounts=array_filter($finance->accounts(),static fn(array$a):bool=>$a['type']!=='credit_card');$categories=$finance->categories('income');}catch(Throwable$ex){error_log('Service orders page: '.$ex->getMessage());$data=['rows'=>[],'indicators'=>array_fill_keys(['draft','open','in_progress','completed','cancelled'],0)];$customers=$members=$accounts=$categories=[];}$flash=$_SESSION['service_orders_flash']??null;unset($_SESSION['service_orders_flash']);$labels=['draft'=>'Rascunho','open'=>'Aberta','in_progress'=>'Em andamento','completed'=>'Concluída','cancelled'=>'Cancelada'];
?>
<?php if(is_array($flash)):?><p class="finance-flash finance-flash-<?= $e($flash[0]) ?>"><?= $e($flash[1]) ?></p><?php endif;?>
<section class="card finance-workspace" aria-labelledby="orders-title"><div class="finance-toolbar"><div><h2 id="orders-title">Ordens de serviço</h2><p class="muted">Serviços, itens e cobranças vinculadas sem alterar saldos antes do recebimento.</p></div><?php if($canManage):?><button class="primary" type="button" data-finance-open="service-order-dialog">+ Nova ordem</button><?php endif;?></div>
<div class="finance-goal-summary is-four"><?php foreach(['draft'=>'Rascunhos','open'=>'Abertas','in_progress'=>'Em andamento','completed'=>'Concluídas']as$key=>$label):?><div class="finance-goal-stat finance-indicator is-neutral"><span><?= $label ?></span><strong><?= (int)$data['indicators'][$key] ?></strong></div><?php endforeach;?></div>
<form class="finance-filter-bar" method="get" data-swap-get><label>Situação<select name="situacao"><option value="">Todas</option><?php foreach($labels as$key=>$label):?><option value="<?= $e($key) ?>"<?= ($_GET['situacao']??'')===$key?' selected':'' ?>><?= $e($label) ?></option><?php endforeach;?></select></label><label>Cliente<select name="cliente"><option value="">Todos</option><?php foreach($customers as$c):?><option value="<?= (int)$c['id'] ?>"<?= (int)($_GET['cliente']??0)===(int)$c['id']?' selected':'' ?>><?= $e($c['trade_name']?:$c['legal_name']) ?></option><?php endforeach;?></select></label><button class="finance-button">Filtrar</button></form>
<?php if($data['rows']===[]):?><div class="finance-empty"><h3>Nenhuma ordem de serviço</h3><p>Cadastre a primeira ordem para organizar a execução e a cobrança.</p></div><?php else:?><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>Número</th><th>Cliente</th><th>Responsável</th><th>Situação</th><th>Total</th><th>Cobrança</th><th>Ações</th></tr></thead><tbody><?php foreach($data['rows']as$row):?><tr><td><strong><?= $e($row['order_number']) ?></strong><details><summary>Itens e histórico</summary><?php foreach($row['items']as$item):?><small><?= $e($item['description']) ?> · <?= $e(number_format((int)$item['quantity_milli']/1000,3,',','.')) ?> × <?= $e(Finance::money((int)$item['unit_price_cents'])) ?> = <?= $e(Finance::money((int)$item['total_cents'])) ?></small><br><?php endforeach;?><?php foreach($row['attachments']as$file):?><a class="entry-chip is-file" href="/minha-conta/ordens-de-servico/anexo/<?= (int)$file['id'] ?>" download><?= $e($file['original_name']) ?></a><?php endforeach;?></details></td><td><?= $e($row['customer_name']) ?></td><td><?= $e($row['responsible_name']?:'Não definido') ?></td><td><span class="finance-badge <?= $row['status']==='completed'?'is-paid':($row['status']==='cancelled'?'is-muted':'is-open') ?>"><?= $e($labels[$row['status']]) ?></span></td><td><?= $e(Finance::money((int)$row['total_cents'])) ?></td><td><?= $row['receivable_entry_id']!==null?'<a href="'.$e(\Moves\Services\AppUrl::section('receber')).'">Vinculada</a>':'Não gerada' ?></td><td class="finance-actions"><?php if($canManage&&$row['status']!=='cancelled'):?><form method="post" action="/minha-conta/ordens-de-servico/situacao"><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><select name="status" aria-label="Nova situação"><?php foreach($labels as$key=>$label):?><option value="<?= $e($key) ?>"<?= $row['status']===$key?' selected':'' ?>><?= $e($label) ?></option><?php endforeach;?></select><button>Atualizar</button></form><?php endif;?><?php if($canManage&&$row['receivable_entry_id']===null&&$row['status']!=='cancelled'):?><button type="button" data-finance-open="order-charge-<?= (int)$row['id'] ?>">Gerar cobrança</button><?php endif;?></td></tr>
<?php if($canManage&&$row['receivable_entry_id']===null&&$row['status']!=='cancelled'):?><dialog class="finance-dialog" id="order-charge-<?= (int)$row['id'] ?>"><form method="post" action="/minha-conta/ordens-de-servico/gerar-cobranca" data-finance-form><header><h2>Gerar cobrança · <?= $e($row['order_number']) ?></h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Vencimento<input type="date" name="due_date" value="<?= $e($row['due_date']?:date('Y-m-d')) ?>" required></label><label>Conta prevista<select name="account_id" required><?php foreach($accounts as$a):?><option value="<?= (int)$a['id'] ?>"><?= $e($a['name']) ?></option><?php endforeach;?></select></label><label>Categoria<select name="category_id"><option value="">Sem categoria</option><?php foreach($categories as$c):?><option value="<?= (int)$c['id'] ?>"><?= $e($c['name']) ?></option><?php endforeach;?></select></label><input type="hidden" name="payment_method" value="other"><footer><button type="button" data-finance-close>Cancelar</button><button class="primary">Criar em Receber</button></footer></form></dialog><?php endif;?><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($canManage):?><dialog class="finance-dialog" id="service-order-dialog"><form method="post" action="/minha-conta/ordens-de-servico/salvar" enctype="multipart/form-data" data-finance-form><header><h2>Nova ordem de serviço</h2><button type="button" data-finance-close>×</button></header><input type="hidden" name="csrf_token" value="<?= $e($csrf) ?>"><input type="hidden" name="idempotency_key" value="<?= $e(bin2hex(random_bytes(16))) ?>"><label>Cliente<select name="customer_id" required><option value="">Selecione</option><?php foreach($customers as$c):?><option value="<?= (int)$c['id'] ?>"><?= $e($c['trade_name']?:$c['legal_name']) ?></option><?php endforeach;?></select></label><label>Descrição<textarea name="description" maxlength="5000"></textarea></label><div class="finance-dialog-row"><label>Responsável<select name="responsible_user_id"><option value="">Não definido</option><?php foreach($members as$m):if($m['status']==='active'):?><option value="<?= (int)$m['user_id'] ?>"><?= $e(trim($m['first_name'].' '.$m['last_name'])) ?></option><?php endif;endforeach;?></select></label><label>Início<input type="date" name="start_date" value="<?= $e(date('Y-m-d')) ?>"></label><label>Prazo<input type="date" name="due_date"></label></div><fieldset><legend>Serviço ou item</legend><div class="finance-dialog-row"><label>Tipo<select name="item_type[]"><option value="service">Serviço</option><option value="item">Item</option></select></label><label>Descrição<input name="item_description[]" required></label></div><div class="finance-dialog-row"><label>Quantidade<input name="item_quantity[]" value="1" inputmode="decimal" required></label><label>Valor unitário<input name="item_unit_price[]" inputmode="decimal" placeholder="0,00" required></label><label>Desconto do item<input name="item_discount[]" inputmode="decimal" placeholder="0,00"></label></div></fieldset><label>Desconto geral<input name="discount" inputmode="decimal" placeholder="0,00"></label><label>Observações<textarea name="notes" maxlength="5000"></textarea></label><label>Anexos<input type="file" name="attachments[]" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.txt"></label><footer><button type="button" data-finance-close>Cancelar</button><button class="primary">Salvar rascunho</button></footer></form></dialog><?php endif;?>
